const products = [
  { asin: 'B08N5WRWNW', title: 'PowerBlend Pro Protein Powder', category: 'Nutrition' },
  { asin: 'B09K2LMXPQ', title: 'NutriMix Daily Greens Powder 30srv', category: 'Nutrition' },
  { asin: 'B07XQZR9TK', title: 'HydroMax Electrolyte Tablets', category: 'Hydration' },
  { asin: 'B08P4WNVJS', title: 'IronCore Resistance Bands Set', category: 'Fitness Equipment' },
  { asin: 'B09LKRTYUP', title: 'RecoverFast Foam Roller Pro', category: 'Recovery' },
  { asin: 'B08MNBVCXZ', title: 'SlimFit Compression Leggings', category: 'Apparel' },
  { asin: 'B07QWERTY12', title: 'MegaWhey Isolate 5lb', category: 'Nutrition' },
  { asin: 'B09ZXCVBNM', title: 'CorePulse Ab Wheel Roller', category: 'Fitness Equipment' }
];
const statuses = ['In Stock', 'In Stock', 'In Stock', 'Low Stock', 'Out of Stock'];

const rows = [];
const now = new Date();

for (const product of products) {
  for (let w = 0; w < 10; w++) {
    const daysAgo = w * 7 + Math.floor(Math.random() * 3);
    const date = new Date(now.getTime() - daysAgo * 86400000);
    const orderedUnits = Math.floor(Math.random() * 300 + 20);
    const shippedUnits = Math.floor(orderedUnits * (Math.random() * 0.15 + 0.80));
    const unitPrice = parseFloat((Math.random() * 60 + 15).toFixed(2));
    const orderedRevenue = parseFloat((orderedUnits * unitPrice).toFixed(2));
    const shippedRevenue = parseFloat((shippedUnits * unitPrice).toFixed(2));
    const glanceViews = Math.floor(Math.random() * 5000 + 200);
    const convRate = parseFloat((orderedUnits / glanceViews * 100).toFixed(2));
    const returns = Math.floor(shippedUnits * (Math.random() * 0.05));

    rows.push({
      date: date.toISOString().split('T')[0],
      asin: product.asin,
      product_title: product.title,
      category: product.category,
      ordered_units: orderedUnits,
      ordered_revenue: orderedRevenue,
      shipped_units: shippedUnits,
      shipped_revenue: shippedRevenue,
      glance_views: glanceViews,
      conversion_rate: convRate,
      customer_returns: returns,
      replenishment_status: statuses[Math.floor(Math.random() * statuses.length)]
    });
  }
}

return [{ json: { data: rows, count: rows.length } }];
